 public void SaveForUpdate(){SaveDraft();if(dirty)throw new IOException("草稿尚未成功保存，暂不重启。请检查本地存储后重试。");}
 public bool IsEvaluating{get{return busy;}}
 void ApplyPreferences(){if(editor!=null){editor.SetFontSize(AppSettings.EditorFont);editor.SetAppearance(AppSettings.Night);}}
 void UpdatePosition(){if(editor==null||position==null)return;int index=editor.Input.CaretIndex,line=editor.Input.GetLineIndexFromCharacterIndex(index);if(line<0)return;int start=editor.Input.GetCharacterIndexFromLineIndex(line);string text="第 "+(line+1)+" 行 · 第 "+(index-start+1)+" 列";if(position.Text!=text){position.Text=text;PositionChangeCount++;}}
 void SetDraftState(string text){if(draftStatus.Text!=text){draftStatus.Text=text;DraftStateChangeCount++;}}
 void Filter(){if(list==null)return;SaveDraft();int selected=current==null?1:current.Id;filtering=true;list.Items.Clear();string query=search.Text.Trim();foreach(var p in bank.Where(p=>(category.SelectedIndex<=0||p.Category==category.SelectedItem.ToString())&&(query==""||p.Title.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||p.Id.ToString().Contains(query))))list.Items.Add(new ListBoxItem{Content=p.ToString()+(best.ContainsKey(p.Id)&&best[p.Id]>=99.95?"  ✓":""),Tag=p});filtering=false;var item=list.Items.Cast<ListBoxItem>().FirstOrDefault(i=>((Problem)i.Tag).Id==selected)??list.Items.Cast<ListBoxItem>().FirstOrDefault();if(item!=null){list.SelectedItem=item;return;}current=null;knowledge.IsEnabled=hint.IsEnabled=false;title.Text="没有匹配的题目";statement.Text="请清空搜索框，或选择其他分类。";sample.Text="";loading=true;editor.Text="";loading=false;run.IsEnabled=false;ResetResults();}
 void SelectProblem(){if(filtering)return;var item=list.SelectedItem as ListBoxItem;if(item==null)return;SaveDraft();current=(Problem)item.Tag;title.Text=current.Id.ToString("00")+"  "+current.Title;subtitle.Text=current.Category+"  /  "+(best.ContainsKey(current.Id)?"历史最高 "+best[current.Id].ToString("0.#")+" 分":"尚未评测");statement.Text=current.Statement+"\n\n只输出题目要求的结果，勿添加“请输入”等提示。";var example=Bank.Generate(current.Id,new Random(123),-1);sample.Text="示例输入\n"+example.Input.TrimEnd('\r','\n')+"\n示例输出\n"+example.Expected;
  string code;if(!drafts.TryGetValue(current.Id,out code)){try{code=File.Exists(DraftPath(current.Id))?File.ReadAllText(DraftPath(current.Id),Encoding.UTF8):Starter;}catch{code=Starter;}}loading=true;editor.Text=code;editor.Input.Document.UndoStack.ClearAll();loading=false;dirty=false;SetDraftState("自动保存已启用");ResetResults();run.IsEnabled=knowledge.IsEnabled=hint.IsEnabled=!busy;editor.RefreshView();UpdatePosition();GlassMotion.Reveal(statement);GlassMotion.Reveal(sample);}
 void ClearPracticeWarning(){warningBanner.Visibility=Visibility.Collapsed;warningText.Text="";score.Foreground=Theme.Blue;}
 void ShowPracticeWarning(Evaluation ev){string message=PracticeFeedback.Warning(ev);warningText.Text=message;warningBanner.Visibility=message==""?Visibility.Collapsed:Visibility.Visible;score.Foreground=message==""?Theme.Blue:Theme.B("#C05235");if(message!=""){summary.Text=!ev.Compiled?"得分警告 · 编译失败":ev.Cases.Any(c=>c.Run.Failure!=""||c.Run.ExitCode!=0)?"得分警告 · 运行异常":"得分警告 · 未达60分";status.Text="可直接修改代码后重新评测 · 详细原因见右侧";}}
 void ResetResults(){ClearPracticeWarning();evaluation=null;score.Text="—";summary.Text="等待提交";breakdown.Text="随机 60 · 边界 20 · 运行 10 · 简洁 10";progress.Value=0;progress.Visibility=Visibility.Hidden;results.IsEnabled=retest.IsEnabled=false;outputCases.Items.Clear();outputDetail.Text="提交后显示实际输出、预期输出与诊断。";}
 string DraftPath(int id){return System.IO.Path.Combine(Engine.DataRoot,"drafts",id.ToString("00")+".c");}
 void SaveDraft(){if(current==null||editor==null||loading)return;drafts[current.Id]=editor.Text;if(!dirty)return;if(preview){dirty=false;SetDraftState("已保存 · 预览模式");return;}try{Directory.CreateDirectory(System.IO.Path.GetDirectoryName(DraftPath(current.Id)));File.WriteAllText(DraftPath(current.Id),editor.Text,new UTF8Encoding(false));dirty=false;SetDraftState("已自动保存");}catch(Exception ex){SetDraftState("保存失败");status.Text="草稿保存失败："+ex.Message;}}
 void LoadScores(){try{string file=System.IO.Path.Combine(Engine.DataRoot,"scores.tsv");if(!File.Exists(file))return;foreach(string line in File.ReadAllLines(file)){string[] a=line.Split('\t');int id;double value;if(a.Length==2&&int.TryParse(a[0],out id)&&double.TryParse(a[1],NumberStyles.Float,CultureInfo.InvariantCulture,out value))best[id]=value;}}catch{}}
 void SaveScores(){try{File.WriteAllLines(System.IO.Path.Combine(Engine.DataRoot,"scores.tsv"),best.OrderBy(x=>x.Key).Select(x=>x.Key+"\t"+x.Value.ToString(CultureInfo.InvariantCulture)).ToArray());}catch(Exception ex){status.Text="成绩保存失败："+ex.Message;}}
 void UpdateStats(){stats.Text="累计得分\n"+best.Where(x=>bank.Any(p=>p.Id==x.Key)).Sum(x=>x.Value).ToString("0.#")+" / "+(bank.Count*100)+" 分\n\n已练习 "+best.Count+" / "+bank.Count+" 题\n满分通过 "+best.Count(x=>x.Value>=99.95)+" 题";}
 void SetBusy(bool value){busy=value;list.IsEnabled=category.IsEnabled=search.IsEnabled=hint.IsEnabled=knowledge.IsEnabled=open.IsEnabled=save.IsEnabled=reset.IsEnabled=!value;editor.Input.IsReadOnly=value;editor.UpdateHistory();run.IsEnabled=!value&&current!=null;stop.IsEnabled=value;results.IsEnabled=retest.IsEnabled=!value&&evaluation!=null;}
 public async Task Evaluate(bool same){if(busy||current==null)return;ClearPracticeWarning();SaveDraft();Problem problem=current;string code=editor.Text;int seed=same&&evaluation!=null?evaluation.Seed:NewSeed();evaluation=null;outputCases.Items.Clear();outputDetail.Text="正在编译和运行…";score.Text="…";summary.Text="正在编译与测试";breakdown.Text="正在准备 28 组测试数据";progress.Value=0;progress.Visibility=Visibility.Visible;cancel=new CancellationTokenSource();SetBusy(true);status.Text="正在评测："+problem.Title;
  try{var ev=await Task.Run(()=>Engine.Judge(problem,code,seed,cancel.Token,(done,total)=>{if(!closed)Dispatcher.BeginInvoke((Action)(()=>{progress.Value=done*100.0/total;status.Text="正在测试 "+done+" / "+total+" · "+problem.Title;}));}));evaluation=ev;PopulateOutputs();score.Text=ev.Score.ToString("0.#");int passed=ev.Cases.Count(x=>x.Passed);summary.Text=ev.Compiled?(passed==ev.Cases.Count?"全部通过":"通过 "+passed+" / "+ev.Cases.Count):"编译失败";breakdown.Text="随机 "+ev.NormalScore.ToString("0.#")+"/60 · 边界 "+ev.EdgeScore.ToString("0.#")+"/20 · 运行 "+ev.QualityScore.ToString("0.#")+"/10 · 简洁 "+(ev.LineScore+ev.SizeScore).ToString("0.#")+"/10";
   if(!preview){if(!best.ContainsKey(problem.Id)||ev.Score>best[problem.Id])best[problem.Id]=ev.Score;SaveScores();UpdateStats();foreach(ListBoxItem item in list.Items){var p=(Problem)item.Tag;item.Content=p.ToString()+(best.ContainsKey(p.Id)&&best[p.Id]>=99.95?"  ✓":"");}subtitle.Text=problem.Category+" / 历史最高 "+best[problem.Id].ToString("0.#")+" 分";}status.Text="评测完成 · 种子 "+seed+" · 点击“查看结果与报告”检查详细数据";ShowPracticeWarning(ev);if(warningBanner.Visibility!=Visibility.Visible&&ev.Compiled&&ev.Score>=90)celebration.Play(ev.Score);
  }catch(OperationCanceledException){score.Text="—";summary.Text="已停止";outputDetail.Text="评测已停止。";breakdown.Text="评测未完成，不计算得分";status.Text="可修改代码后重新提交";}catch(Exception ex){score.Text="—";summary.Text="无法完成评测";outputDetail.Text=ex.Message;breakdown.Text=ex.Message;status.Text="评测环境错误："+ex.Message;}finally{SetBusy(false);cancel.Dispose();cancel=null;progress.Visibility=Visibility.Hidden;}
 }
 static int NewSeed(){byte[] bytes=new byte[4];using(var rng=System.Security.Cryptography.RandomNumberGenerator.Create())rng.GetBytes(bytes);return BitConverter.ToInt32(bytes,0)&int.MaxValue;}
 void ShowAnswer(){if(current==null||busy)return;var dialog=new AnswerWindow(current){Owner=this};dialog.ShowDialog();if(dialog.ImportAnswer)ImportReference();}
 public void ImportReference(){if(current==null||busy)return;SaveDraft();try{if(!preview){string dir=System.IO.Path.Combine(Engine.DataRoot,"answer-import-backups");Directory.CreateDirectory(dir);File.WriteAllText(System.IO.Path.Combine(dir,current.Id.ToString("00")+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".c"),editor.Text,new UTF8Encoding(false));}editor.Text=current.Reference;SaveDraft();status.Text="标准答案已导入 · 原草稿已备份";editor.Input.Focus();}catch(Exception ex){AppDialog.Show(this,ex.Message,"答案导入失败");}}
 void PopulateOutputs(){outputCases.Items.Clear();if(evaluation==null)return;if(!evaluation.Compiled){outputDetail.Text=Theme.CompileAdvice(evaluation.Compiler,false);return;}int selected=0;bool found=false;for(int i=0;i<evaluation.Cases.Count;i++){var c=evaluation.Cases[i];outputCases.Items.Add("用例 "+(i+1)+" · "+(c.Test.Edge?"边界":"随机")+" · "+(c.Passed?"通过":"失败"));if(!found&&!c.Passed){selected=i;found=true;}}outputCases.SelectedIndex=selected;}
 void ShowOutput(){if(evaluation==null||outputCases.SelectedIndex<0)return;var c=evaluation.Cases[outputCases.SelectedIndex];outputDetail.Text="输入\n"+c.Test.Input.TrimEnd()+"\n\n实际输出\n"+(c.Run.Output==""?"（无输出）":c.Run.Output.TrimEnd())+"\n\n预期输出\n"+c.Test.Expected.TrimEnd()+"\n\n诊断\n"+c.Diagnosis+"\n\n耗时 "+c.Run.Millis.ToString("0.0")+" ms\n退出码 "+c.Run.ExitCode+(c.Run.Error==""?"":"\n标准错误 / 中文解释\n"+Diagnostics.Explain(c.Run.Error));}
 void OpenResults(){if(evaluation==null)return;new ResultsWindow(evaluation,current){Owner=this}.ShowDialog();}
 void Import(){var d=new Microsoft.Win32.OpenFileDialog{Filter="C 源程序 (*.c)|*.c|文本文件 (*.txt)|*.txt|所有文件 (*.*)|*.*"};if(d.ShowDialog(this)==true)try{if(new FileInfo(d.FileName).Length>1500000)throw new Exception("文件过大。");string text=File.ReadAllText(d.FileName,Encoding.UTF8);if(text.Length>150000)throw new Exception("代码超过 150000 字符。");editor.Text=text;}catch(Exception ex){AppDialog.Show(this,ex.Message,"导入失败");}}
 void SaveCode(){var d=new Microsoft.Win32.SaveFileDialog{Filter="C 源程序 (*.c)|*.c",FileName=current==null?"answer.c":current.Id.ToString("00")+"_answer.c"};if(d.ShowDialog(this)==true)try{File.WriteAllText(d.FileName,editor.Text,new UTF8Encoding(false));status.Text="已保存源程序";}catch(Exception ex){AppDialog.Show(this,ex.Message,"保存失败");}}
 void EditorKeys(object sender,KeyEventArgs e){if(editor.HandleHistory(e))return;if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.Enter){e.Handled=true;Dispatcher.BeginInvoke((Action)(async()=>await Evaluate(false)));}else if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.S){e.Handled=true;SaveCode();}else if(e.Key==Key.Tab){e.Handled=true;int start=editor.Input.SelectionStart;editor.Input.SelectedText="    ";editor.Input.Select(start+4,0);}else if(e.Key==Key.Enter&&Keyboard.Modifiers==ModifierKeys.None){e.Handled=true;int selected=editor.Input.SelectionStart;int line=editor.Input.GetLineIndexFromCharacterIndex(selected);int start=line<0?0:editor.Input.GetCharacterIndexFromLineIndex(line);string before=editor.Text.Substring(Math.Max(0,start),Math.Max(0,selected-start));string indent=System.Text.RegularExpressions.Regex.Match(before,@"^[ \t]*").Value;if(before.TrimEnd().EndsWith("{"))indent+="    ";string newline=editor.Text.Contains("\r\n")?"\r\n":"\n";editor.Input.SelectedText=newline+indent;editor.Input.Select(selected+newline.Length+indent.Length,0);}}
 void HandleClosing(object sender,CancelEventArgs e){if(busy){if(cancel!=null)cancel.Cancel();e.Cancel=true;status.Text="正在停止运行，请稍后再关闭窗口";}else SaveDraft();}
 public void PreviewSize(double width,double height){WindowState=WindowState.Normal;var root=(FrameworkElement)Content;root.Width=width;root.Height=height;SizeToContent=SizeToContent.WidthAndHeight;UpdateLayout();}
 public async Task Preview(string path,bool clean,double dpi=96,double width=1400,double height=900){PreviewSize(width,height);if(!clean){editor.Text=current.Reference;await Evaluate(false);}await Task.Delay(1200);Theme.Capture((FrameworkElement)Content,path,dpi);Close();}
}
