  if(args.Length>=2&&args[0]=="--failure-screenshot"){var failure=new FailureWindow("编译失败 · 封印反噬",true);failure.Width=1600;failure.Height=1000;failure.ContentRendered+=async(s,e)=>{await Task.Delay(2150);Theme.Capture((FrameworkElement)failure.Content,args[1],args.Length>=3?double.Parse(args[2],CultureInfo.InvariantCulture):96);failure.Close();};app.Run(failure);return;}
